var box = root.querySelector('.mtd-metric-cube-box');
var tabs = Array.prototype.slice.call(root.querySelectorAll('.mtd-metric-cube-tab'));
var auto = root.querySelector('.mtd-metric-cube-auto');
var reduce = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
var angle = 0, idx = 0, timer = null;

function paint() {
  box.style.setProperty('--mtd-mc-y', angle + 'deg');
  tabs.forEach(function (t, n) { t.setAttribute('aria-pressed', n === idx ? 'true' : 'false'); });
}
function goTo(i) {
  var want = ((-90 * i) % 360 + 360) % 360;
  var cur = ((angle % 360) + 360) % 360;
  var d = ((want - cur) % 360 + 360) % 360;
  if (d > 180) { d -= 360; }
  angle += d; idx = i; paint();
}
function stop() { if (timer) { clearInterval(timer); timer = null; } }
function start() {
  stop();
  timer = setInterval(function () {
    if (!root.isConnected) { stop(); return; }
    goTo((idx + 1) % 4);
  }, 2800);
}
tabs.forEach(function (t) {
  t.addEventListener('click', function () {
    goTo(parseInt(t.getAttribute('data-i'), 10) || 0);
    if (auto.getAttribute('aria-pressed') === 'true') { start(); }
  });
});
auto.addEventListener('click', function () {
  var on = auto.getAttribute('aria-pressed') !== 'true';
  auto.setAttribute('aria-pressed', on ? 'true' : 'false');
  if (on) { start(); } else { stop(); }
});
paint();
if (reduce) { auto.setAttribute('aria-pressed', 'false'); } else { start(); }

