js:
var ring = root.querySelector('.mtd-ring-carousel-ring');
var cells = Array.prototype.slice.call(root.querySelectorAll('.mtd-ring-carousel-cell'));
var dots = Array.prototype.slice.call(root.querySelectorAll('.mtd-ring-carousel-dots i'));
var count = root.querySelector('.mtd-ring-carousel-count');
var n = cells.length, r = 0, idx = 0;

function paint() {
  ring.style.setProperty('--mtd-rc-r', r);
  cells.forEach(function (c, i) { c.setAttribute('data-on', i === idx ? '1' : '0'); });
  dots.forEach(function (d, i) { d.setAttribute('data-on', i === idx ? '1' : '0'); });
  count.textContent = (idx + 1) + ' / ' + n;
}
function goTo(i) {
  var want = ((i % n) + n) % n;
  var cur = ((r % n) + n) % n;
  var d = ((want - cur) % n + n) % n;
  if (d > n / 2) { d -= n; }
  r += d; idx = want; paint();
}
function step(dir) { goTo(idx + dir); }

cells.forEach(function (c, i) {
  c.addEventListener('click', function () { goTo(i); });
  c.addEventListener('focus', function () { goTo(i); });
});
Array.prototype.slice.call(root.querySelectorAll('.mtd-ring-carousel-arw')).forEach(function (b) {
  b.addEventListener('click', function () { step(parseInt(b.getAttribute('data-dir'), 10)); });
});
root.addEventListener('keydown', function (e) {
  if (e.key === 'ArrowRight') { step(1); e.preventDefault(); }
  else if (e.key === 'ArrowLeft') { step(-1); e.preventDefault(); }
});
paint();

