var scene = root.querySelector('.mtd-depth-card-scene');
var plate = root.querySelector('.mtd-depth-card-plate');
var reduce = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;

function reset() {
  scene.setAttribute('data-live', '0');
  scene.style.setProperty('--mtd-dc-rx', '0deg');
  scene.style.setProperty('--mtd-dc-ry', '0deg');
  scene.style.setProperty('--mtd-dc-mx', '50%');
  scene.style.setProperty('--mtd-dc-my', '35%');
}
function track(e) {
  if (reduce) { return; }
  var b = plate.getBoundingClientRect();
  var px = (e.clientX - b.left) / b.width;
