  if (reduce) { return; }
  scene.setAttribute('data-live', '0');
  scene.style.setProperty('--mtd-dc-ry', '-9deg');
  scene.style.setProperty('--mtd-dc-rx', '7deg');
  scene.style.setProperty('--mtd-dc-mx', '30%');
