js:
var plates = {};
Array.prototype.slice.call(root.querySelectorAll('.mtd-iso-stack-plate')).forEach(function (p) {
  plates[p.getAttribute('data-i')] = p;
});
var items = Array.prototype.slice.call(root.querySelectorAll('.mtd-iso-stack-item'));
var picked = '1';

function paint(hover) {
  Object.keys(plates).forEach(function (k) {
    plates[k].setAttribute('data-lift', (k === picked || k === hover) ? '1' : '0');
  });
  items.forEach(function (b) {
    b.setAttribute('aria-pressed', b.getAttribute('data-i') === picked ? 'true' : 'false');
  });
}
items.forEach(function (b) {
  var i = b.getAttribute('data-i');
  b.addEventListener('pointerenter', function () { paint(i); });
  b.addEventListener('pointerleave', function () { paint(null); });
  b.addEventListener('focus', function () { paint(i); });
  b.addEventListener('blur', function () { paint(null); });
  b.addEventListener('click', function () { picked = i; paint(i); });
});
paint(null);

