js:
var coin = root.querySelector('.mtd-coin-flip-coin');
var btn = root.querySelector('.mtd-coin-flip-go');
var res = root.querySelector('.mtd-coin-flip-res');
var outH = root.querySelector('.mtd-coin-flip-h');
var outT = root.querySelector('.mtd-coin-flip-t');
var reduce = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
var x = 0, heads = true, h = 0, t = 0, busy = false;

btn.addEventListener('click', function () {
  if (busy) { return; }
  busy = true;
  btn.disabled = true;
  res.textContent = 'Tossing…';
  var win = Math.random() < 0.5;
  x += (reduce ? 0 : 720) + (win === heads ? 0 : 180);
  heads = win;
  coin.style.setProperty('--mtd-cf-x', x + 'deg');
  root.setAttribute('data-go', '1');
  setTimeout(function () {
    if (!root.isConnected) { return; }
    root.setAttribute('data-go', '0');
    if (win) { h += 1; } else { t += 1; }
    outH.textContent = h;
    outT.textContent = t;
