var out=root.querySelector('.fx-out');
var cols=[].slice.call(root.querySelectorAll('.fx-col'));
function pick(el){cols.forEach(function(c){c.classList.toggle('fx-on',c===el);});out.textContent=el.getAttribute('data-d')+' · '+el.getAttribute('data-v');}
cols.forEach(function(c){
c.setAttribute('aria-label',c.getAttribute('data-d')+', '+c.getAttribute('data-v')+' sessions');
c.addEventListener('pointerenter',function(){pick(c);});
c.addEventListener('focus',function(){pick(c);});
c.addEventListener('click',function(){pick(c);});
});

css:
.mtd-gate-fold{box-sizing:border-box;font-family:system-ui,-apple-system,Segoe UI,Roboto,sans-serif;background:#0a0710;border:1px solid #2c1c3d;border-radius:16px;padding:16px;color:#f0e4f7;display:flex;flex-direction:column;gap:12px}
.mtd-gate-fold *{box-sizing:border-box}
.mtd-gate-fold .gf-scene{position:relative;width:236px;max-width:100%;height:152px;perspective:900px}
.mtd-gate-fold .gf-inner{position:absolute;left:0;top:0;right:0;bottom:0;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:5px;padding:14px;text-align:center;border-radius:12px;border:1px solid #46295e;background:radial-gradient(85% 85% at 50% 24%,#2a1740,#0d0715 78%);visibility:hidden;transition:visibility 0s linear .36s}
.mtd-gate-fold.is-open .gf-inner{visibility:visible;transition-delay:0s}
.mtd-gate-fold .gf-kicker{font-size:9px;letter-spacing:.28em;text-transform:uppercase;color:#c79bea}
.mtd-gate-fold .gf-ttl{font-size:20px;font-weight:620;letter-spacing:-.01em;color:#fdf3ff}
.mtd-gate-fold .gf-meta{font-size:11.5px;color:#b79fd0}
.mtd-gate-fold .gf-rsvp{margin-top:8px;font:inherit;font-size:12px;font-weight:600;padding:8px 18px;border-radius:99px;border:1px solid #e8c37a;background:linear-gradient(120deg,#f4d79a,#d9a13f);color:#2a1704;cursor:pointer;transition:filter .18s,transform .12s}
.mtd-gate-fold .gf-rsvp:hover{filter:brightness(1.08)}
.mtd-gate-fold .gf-rsvp:active{transform:translateY(1px)}
.mtd-gate-fold .gf-rsvp.gf-yes{background:none;color:#f4d79a}
.mtd-gate-fold .gf-rsvp:focus-visible{outline:2px solid #e8c37a;outline-offset:3px}
.mtd-gate-fold .gf-door{position:absolute;top:0;bottom:0;width:50%;transform-style:preserve-3d;transition:transform .82s cubic-bezier(.62,.04,.2,1)}
.mtd-gate-fold .gf-l{left:0;transform-origin:left center}
.mtd-gate-fold .gf-r{right:0;transform-origin:right center}
.mtd-gate-fold.is-open .gf-l{transform:rotateY(-114deg)}
.mtd-gate-fold.is-open .gf-r{transform:rotateY(114deg)}
.mtd-gate-fold .gf-face{position:absolute;left:0;top:0;right:0;bottom:0;display:flex;align-items:center;justify-content:center;backface-visibility:hidden;border:1px solid #5b3a75}
.mtd-gate-fold .gf-l .gf-face{border-radius:12px 0 0 12px;border-right:0}
.mtd-gate-fold .gf-r .gf-face{border-radius:0 12px 12px 0;border-left:0}
.mtd-gate-fold .gf-out{background:linear-gradient(135deg,#43265a,#1d1029 62%,#160c20);box-shadow:inset 0 0 40px #00000055}
.mtd-gate-fold .gf-in{transform:rotateY(180deg);background:repeating-linear-gradient(135deg,#180e22 0 6px,#140b1d 6px 12px);border-color:#33203f}
.mtd-gate-fold .gf-mono{font-size:14px;font-weight:400;letter-spacing:.34em;color:#e8c37a;opacity:.85;padding-left:.24em}
.mtd-gate-fold .gf-seal{width:44px;height:44px;border-radius:50%;display:flex;align-items:center;justify-content:center;font-size:15px;font-weight:600;color:#2a1704;background:linear-gradient(140deg,#f4d79a,#c9963f);box-shadow:0 4px 14px #00000066}
.mtd-gate-fold .gf-key{font:inherit;font-size:12px;padding:9px 14px;border-radius:10px;border:1px solid #46295e;background:#150c1f;color:#dcc7ee;cursor:pointer;transition:background .18s,border-color .18s}
.mtd-gate-fold .gf-key:hover{background:#20122e;border-color:#6d4390}
.mtd-gate-fold .gf-key:focus-visible{outline:2px solid #c79bea;outline-offset:2px}
@media (prefers-reduced-motion: reduce){
.mtd-gate-fold .gf-door{transition-duration:.001s}
.mtd-gate-fold .gf-inner{transition:none}
}

.mtd-iso-heatmap{box-sizing:border-box;font-family:system-ui,-apple-system,Segoe UI,Roboto,sans-serif;background:#0a0810;border:1px solid #241a38;border-radius:16px;padding:12px 14px 14px;color:#ece6f6;display:flex;flex-direction:column;gap:6px}
.mtd-iso-heatmap *{box-sizing:border-box}
.mtd-iso-heatmap .ih-scene{position:relative;height:168px;perspective:780px}
.mtd-iso-heatmap .ih-field{position:absolute;left:50%;top:52%;display:grid;grid-template-columns:repeat(4,30px);grid-auto-rows:30px;gap:6px;transform-style:preserve-3d;transform:translate(-50%,-50%) rotateX(58deg) rotateZ(-45deg)}
.mtd-iso-heatmap .ih-tl{width:30px;height:30px;padding:0;border:0;border-radius:5px;cursor:pointer;transform:translateZ(var(--mtd-iso-heatmap-z,4px));box-shadow:0 0 0 1px #ffffff14,0 6px 14px #00000066;transition:transform .3s cubic-bezier(.2,.9,.3,1),filter .3s}
.mtd-iso-heatmap .ih-v1{--mtd-iso-heatmap-z:3px;background:linear-gradient(150deg,#2b2a56,#1c1b3c)}
.mtd-iso-heatmap .ih-v2{--mtd-iso-heatmap-z:11px;background:linear-gradient(150deg,#453a86,#2a2358)}
.mtd-iso-heatmap .ih-v3{--mtd-iso-heatmap-z:19px;background:linear-gradient(150deg,#7a3f9e,#4a2467)}
.mtd-iso-heatmap .ih-v4{--mtd-iso-heatmap-z:27px;background:linear-gradient(150deg,#c14a7c,#7c2a52)}
.mtd-iso-heatmap .ih-v5{--mtd-iso-heatmap-z:35px;background:linear-gradient(150deg,#f7a04a,#c74f36)}
.mtd-iso-heatmap .ih-tl:hover,.mtd-iso-heatmap .ih-tl.ih-sel{transform:translateZ(calc(var(--mtd-iso-heatmap-z,4px) + 18px));filter:brightness(1.22)}
.mtd-iso-heatmap .ih-tl.ih-sel{box-shadow:0 0 0 2px #ffd48a,0 8px 18px #00000077}
.mtd-iso-heatmap .ih-tl:focus-visible{outline:2px solid #ffd48a;outline-offset:3px}
.mtd-iso-heatmap .ih-cap{margin:0;display:flex;align-items:baseline;gap:8px}
.mtd-iso-heatmap .ih-cap .ih-t{font-size:13px;font-weight:600;color:#fdf2ff}
.mtd-iso-heatmap .ih-cap .ih-d{font-size:12px;color:#a596c4;font-variant-numeric:tabular-nums}
.mtd-iso-heatmap .ih-legend{display:flex;align-items:center;gap:4px}
.mtd-iso-heatmap .ih-sw{width:16px;height:8px;border-radius:2px}
.mtd-iso-heatmap .ih-lg{margin-left:6px;font-size:10px;letter-spacing:.08em;text-transform:uppercase;color:#7c6f99}
@media (prefers-reduced-motion: reduce){
.mtd-iso-heatmap .ih-tl{transition:none}
.mtd-iso-heatmap .ih-tl:hover,.mtd-iso-heatmap .ih-tl.ih-sel{transform:translateZ(var(--mtd-iso-heatmap-z,4px))}
}

.mtd-split-flap{box-sizing:border-box;font-family:system-ui,-apple-system,Segoe UI,Roboto,sans-serif;background:linear-gradient(180deg,#111010,#080807);border:1px solid #2a2721;border-radius:14px;padding:14px;color:#e9dcc2;display:flex;flex-direction:column;gap:12px;align-items:center}
.mtd-split-flap *{box-sizing:border-box}
.mtd-split-flap .sf-row{display:flex;gap:6px}
.mtd-split-flap .sf-cell{position:relative;display:block;width:34px;height:52px;perspective:190px;border-radius:5px;background:#0a0a09;box-shadow:0 2px 10px #00000088}
.mtd-split-flap .sf-up,.mtd-split-flap .sf-lo,.mtd-split-flap .sf-fa,.mtd-split-flap .sf-fb{position:absolute;left:0;display:block;width:34px;height:26px;overflow:hidden}
.mtd-split-flap .sf-up,.mtd-split-flap .sf-fa{top:0;border-radius:5px 5px 0 0;background:linear-gradient(#26241d,#1a1915);box-shadow:inset 0 1px 0 #ffffff10}
.mtd-split-flap .sf-lo,.mtd-split-flap .sf-fb{top:26px;border-radius:0 0 5px 5px;background:linear-gradient(#161511,#0f0e0b);box-shadow:inset 0 -1px 0 #00000099}
.mtd-split-flap .sf-fa{transform-origin:50% 100%;backface-visibility:hidden;visibility:hidden;z-index:2}
.mtd-split-flap .sf-fb{transform-origin:50% 0;backface-visibility:hidden;visibility:hidden;z-index:2;transform:rotateX(90deg)}
.mtd-split-flap .sf-up{border-bottom:1px solid #050504}
.mtd-split-flap i{position:absolute;left:0;width:34px;height:52px;line-height:52px;text-align:center;font-family:ui-monospace,Menlo,monospace;font-size:29px;font-weight:600;font-style:normal;color:#f4b23c;text-shadow:0 0 12px #f4b23c44}
.mtd-split-flap .sf-up i,.mtd-split-flap .sf-fa i{top:0}
.mtd-split-flap .sf-lo i,.mtd-split-flap .sf-fb i{top:-26px}
.mtd-split-flap .sf-cell.sf-turn .sf-fa{visibility:visible;animation:mtd-split-flap-fall .2s ease-in forwards}
.mtd-split-flap .sf-cell.sf-turn .sf-fb{visibility:visible;animation:mtd-split-flap-rise .2s .2s ease-out forwards}
@keyframes mtd-split-flap-fall{from{transform:rotateX(0deg)}to{transform:rotateX(-90deg)}}
@keyframes mtd-split-flap-rise{from{transform:rotateX(90deg)}to{transform:rotateX(0deg)}}
.mtd-split-flap .sf-foot{display:flex;align-items:center;justify-content:space-between;gap:14px;width:100%}
.mtd-split-flap .sf-lbl{font-size:11px;letter-spacing:.16em;text-transform:uppercase;color:#8b7d63}
.mtd-split-flap .sf-pz{font:inherit;font-size:11px;letter-spacing:.06em;padding:7px 12px;border-radius:9px;border:1px solid #3a3428;background:#171612;color:#e2c88f;cursor:pointer;transition:background .18s,border-color .18s}
.mtd-split-flap .sf-pz:hover{background:#221f18;border-color:#5c5238}
.mtd-split-flap .sf-pz[aria-pressed='true']{color:#f4b23c;border-color:#6b5c34}
.mtd-split-flap .sf-pz:focus-visible{outline:2px solid #f4b23c;outline-offset:2px}
@media (prefers-reduced-motion: reduce){
.mtd-split-flap .sf-cell.sf-turn .sf-fa,.mtd-split-flap .sf-cell.sf-turn .sf-fb{animation-duration:.001s;animation-delay:0s}
}

js:
var cells=[].slice.call(root.querySelectorAll('.sf-cell'));
var btn=root.querySelector('.sf-pz'),row=root.querySelector('.sf-row');
var rm=window.matchMedia('(prefers-reduced-motion: reduce)');
var n=1487,paused=rm.matches,timers=[];
function setCell(cell,ch,k){
var cur=cell.getAttribute('data-c')||'0';
if(cur===ch)return;
cell.setAttribute('data-c',ch);
var up=cell.querySelector('.sf-up i'),lo=cell.querySelector('.sf-lo i');
var fa=cell.querySelector('.sf-fa i'),fb=cell.querySelector('.sf-fb i');
fa.textContent=cur;fb.textContent=ch;up.textContent=ch;lo.textContent=cur;
cell.classList.remove('sf-turn');
void cell.offsetWidth;
cell.classList.add('sf-turn');
clearTimeout(timers[k]);
timers[k]=setTimeout(function(){if(!root.isConnected)return;lo.textContent=ch;cell.classList.remove('sf-turn');},440);
}
function show(v){
var s=String(v);
while(s.length<4){s='0'+s;}
s=s.slice(-4);
cells.forEach(function(c,k){setCell(c,s.charAt(k),k);});
row.setAttribute('aria-label',v+' signups today');
}
function label(){btn.textContent=paused?'Resume':'Pause';btn.setAttribute('aria-pressed',paused?'true':'false');}
btn.addEventListener('click',function(){paused=!paused;label();});
var tick=setInterval(function(){if(!root.isConnected){clearInterval(tick);return;}if(paused)return;n+=1+Math.floor(Math.random()*3);show(n);},2600);
label();
setTimeout(function(){if(!root.isConnected)return;show(n);},260);
